$ErrorActionPreference='SilentlyContinue';$Repo='C:\Users\aaron\Desktop\URAP';$Run=Join-Path $Repo 'artifacts\detached_ard_tvd_generalization_audit_v169';$PidFile=Join-Path $Run 'pid.txt';$MetaFile=Join-Path $Run 'meta.json';$ProgressFile=Join-Path $Run 'progress.json';$Summary='D:\URAP_vatd_rank_results\ard_tvd_generalization_audit_v169\official_summary.json';if(!(Test-Path $PidFile)){Write-Output 'NOT RUNNING: PID file missing';exit 1};$JobPid=[int](Get-Content $PidFile -Raw).Trim();$Process=Get-CimInstance Win32_Process -Filter "ProcessId=$JobPid";if($Process){Write-Output "RUNNING PID: $JobPid";Write-Output "Command: $($Process.CommandLine)"}else{Write-Output "NOT RUNNING PID: $JobPid"};if(Test-Path $MetaFile){$Meta=Get-Content $MetaFile -Raw|ConvertFrom-Json;Write-Output "Start time: $($Meta.start_time)";Write-Output "Stdout log: $($Meta.stdout_log)";Write-Output "Stderr log: $($Meta.stderr_log)"};if(Test-Path $ProgressFile){$Progress=Get-Content $ProgressFile -Raw|ConvertFrom-Json;Write-Output "Progress: $($Progress.done)/$($Progress.total)";Write-Output "Stage: $($Progress.stage)";Write-Output "Last output: $($Progress.updated)";if($Progress.waiting_for){Write-Output "Waiting for: $($Progress.waiting_for) PID=$($Progress.pid)"};if($Progress.error){Write-Output "Error: $($Progress.error)"}}else{Write-Output 'Progress: 0/2'};if(Test-Path $Summary){$Result=Get-Content $Summary -Raw|ConvertFrom-Json;Write-Output "ARD gain: $($Result.ard100.gain_over_vatd_points) points";Write-Output "Selected TVD method: $($Result.tvd_selected_by_validation.name)";Write-Output "TVD gain: $($Result.tvd_selected_by_validation.gain_over_vatd_points) points";Write-Output "Generalization target met: $($Result.generalization_target_met)"}
